k += ButtonBlogDownloadImages_Click;              blogUrlTextBox.KeyDown += BlogUrlTextBox_KeyDown;         }          private async void Form1_Load(object? sender, EventArgs e)         {             try             {                 if (_blogCleanerHandler != null)                 {                     await _blogCleanerHandler.InitializeAsync();                     SetBlogStatus("占쏙옙占쏙옙: 占쏙옙占싸깍옙 占쏙옙占쏙옙占쏙옙 占쌔븝옙 占싹뤄옙");                 }             }             catch (Exception ex)             {                 SetBlogStatus($"占쏙옙占쏙옙: 占십깍옙화 占쏙옙占쏙옙 - {ex.Message}");             }         }          private async void Form1_FormClosing(object? sender, FormClosingEventArgs e)         {             if (_closingInProgress)                 return;              _closingInProgress = true;              try             {                 if (_blogCleanerHandler != null)                 {                     await _blogCleanerHandler.ShutdownAsync();                     _blogCleanerHandler.Dispose();                     _blogCleanerHandler = null;                 }             }             catch             {                 // 占쏙옙占쏙옙 占쏙옙 占쏙옙占쏙옙 占쏙옙占쏙옙             }         }          private void TabControl_SelectedIndexChanged(object? sender, EventArgs e)         {             if (tabControl.SelectedTab == tabPageBlogCleaner)             {                 MinimumSize = _blogMinSize;                  if (WindowState == FormWindowState.Normal)                     Size = _blogFormSize;             }             else             {                 MinimumSize = _defaultMinSize;                  if (WindowState == FormWindowState.Normal)                     Size = _defaultFormSize;             }         }          private void SetMainStatus(string message)         {             if (InvokeRequired)             {                 Invoke(new Action(() => SetMainStatus(message)));                 return;             }              labelStatus.Text = message;         }          privat